(()=>{
 const dialog=document.getElementById('listing-address-dialog'),form=document.getElementById('listing-address-form'),source=document.getElementById('listing-address-source'),fetchButton=document.getElementById('listing-address-fetch'),message=document.getElementById('listing-address-message');let key=null,item=null,controller=null;
 const input=name=>form.elements.namedItem(name);
 function stop(){controller?.abort();controller=null;fetchButton.disabled=!source.value;fetchButton.textContent='Adresse aus Original versuchen'}
 window.openListingAddress=function(nextKey){stop();key=nextKey;item=rows.find(x=>listingKey(x)===key)||savedState[key]?.snapshot;if(!item)return;const address=savedState[key]?.address||item;for(const name of ['street','zipcode','city'])input(name).value=String(address[name]??'');source.replaceChildren();const entries=item.portalListings||[item],seen=new Set();for(const entry of entries){try{const url=new URL(entry.url);if(!['http:','https:'].includes(url.protocol)||seen.has(url.href))continue;seen.add(url.href);const option=document.createElement('option');option.value=url.href;option.textContent=entry.source||'Originalinserat';source.append(option)}catch{}}message.textContent='';fetchButton.disabled=!source.value;dialog.showModal();input('street').focus()};
 document.getElementById('listing-address-close').addEventListener('click',()=>{stop();dialog.close()});dialog.addEventListener('close',stop);dialog.addEventListener('cancel',stop);
 fetchButton.addEventListener('click',async()=>{if(!source.value)return;if(['street','zipcode','city'].some(name=>input(name).value)&&!confirm('Vorhandene Adressangaben durch Angaben aus dem Originalinserat ergänzen oder ersetzen?'))return;stop();const current=new AbortController();controller=current;fetchButton.disabled=true;fetchButton.textContent='Adresse wird gesucht …';message.textContent='';try{const response=await fetch('/api/listings/address',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:source.value}),signal:current.signal});const data=await response.json();if(controller!==current)return;if(!response.ok)throw new Error(data.error||'Keine Adresse auslesbar. Bitte manuell ergänzen.');if(!data.listing?.street)throw new Error('Keine Straße im öffentlichen Inserat gefunden. Bitte manuell ergänzen.');for(const name of ['street','zipcode','city'])if(data.listing[name]!=null&&data.listing[name]!=='')input(name).value=String(data.listing[name]);message.textContent=data.message||'Adresse übernommen. Bitte prüfen und speichern.'}catch(error){if(error.name!=='AbortError'&&controller===current)message.textContent=error.message||'Die Adresse konnte nicht abgerufen werden.'}finally{if(controller===current){controller=null;fetchButton.disabled=!source.value;fetchButton.textContent='Adresse aus Original versuchen'}}});
 form.addEventListener('submit',event=>{event.preventDefault();if(controller){message.textContent='Bitte den Abruf abwarten.';return}if(!form.reportValidity()||!key||!item)return;const previous=savedState[key];const address={street:input('street').value.trim(),zipcode:input('zipcode').value.trim(),city:input('city').value.trim()};savedState[key]={...previous,snapshot:previous?.snapshot||{...item},address};if(!saveState()){if(previous)savedState[key]=previous;else delete savedState[key];message.textContent='Die Adresse konnte nicht gespeichert werden.';return}dialog.close();render();renderObjects()});
})();
